        [StringKey.BeekeeperLogCart] = "A cart of flowers. Bees follow it everywhere.",
        [StringKey.BeekeeperLogWhistle] = "One soft note, and the bees come home.",
        [StringKey.BeekeeperUpgradePractice] = "Practice",
