        [StringKey.BeekeeperUpgradeMorePractice] = "More Practice",
        [StringKey.BeekeeperUpgradeMorePracticeBlurb] = "+%@% bees per click",
        [StringKey.BeekeeperUpgradeSmoker] = "The Smoker",
        [StringKey.BeekeeperUpgradeSmokerBlurb] = "With calm bees, the combs make double honey",
        [StringKey.BeekeeperSmokerTitle] = "THE SMOKER",
        [StringKey.BeekeeperCalmMeterFmt] = "Calm: %@/%@",
        [StringKey.BeekeeperCalmNowFmt] = "The bees are calm: %@ left · honey ×%@",
        [StringKey.BeekeeperPuff] = "Puff the Smoker",
        [StringKey.BeekeeperLogSmokerPuffed] = "You puff the smoker. The hive settles and hums.",
        [StringKey.BeekeeperLogCalmEnded] = "The smoke drifts away.",
        [StringKey.HelpBeekeeperSmokerTitle] = "💨 Catching More & the Smoker",
        [StringKey.HelpBeekeeperSmoker] = "After the Bee-Safe Vacuum, the Shop sells more tools (Bee Lure, Flower Cart, Hive Whistle) and Practice upgrades that make every click catch more. Every catch also brings in a small slice of your free bees (0.1%), so a big swarm of free bees grows faster (up to 10 times what your tool catches).\n\nThe Smoker, also in the Shop, fills a little with every click. When it's full, press Puff the Smoker: for 2 minutes the bees are calm and the combs make double honey.",
        [StringKey.BeekeeperHiveCombs] = "Combs",
