        [StringKey.BeekeeperBuild] = "Build",
        [StringKey.BeekeeperTradingTitle] = "TRADING",
        [StringKey.BeekeeperHippiesName] = "The Hippies",
        [StringKey.BeekeeperWaxPerSecFmt] = "%@ wax / sec",
