        [StringKey.HelpHoneycombSubtitle] = "Una batalla táctica de cartas en cuadrícula de 3×3 inspirada en Triple Triad.",
        [StringKey.HelpCoreGameplayMechanicsTitle] = "🎮 Jugabilidad Principal y Mecánicas",
