        [StringKey.HelpOverviewObjectiveTitle] = "📌 Resumen y Objetivo",
        [StringKey.HelpControlsShortcutsTitle] = "⌨️ Controles y Atajos",
        [StringKey.HelpShortcutClickDragTap] = "Haz clic y arrastra o Toca Carta → Toca Celda",
        [StringKey.HelpShortcutNavigateSelect] = "Navegar / Seleccionar",
        [StringKey.HelpShortcutSelectPlaceCard] = "Seleccionar / Colocar Carta",
        [StringKey.HelpShortcutSelectPlaceSequence] = "Seleccionar / Colocar Secuencia",
        [StringKey.HelpShortcutShowBestAiMove] = "Mostrar Mejor Movimiento de la IA",
        [StringKey.HelpShortcutSplitPairs] = "Dividir Pares",
        [StringKey.HelpShortcutArrowKeys] = "Flechas del Teclado",
        [StringKey.HelpShortcutCQ] = "C / Q",
        [StringKey.HelpShortcutSpaceEnter] = "Barra espaciadora / Intro",
        [StringKey.HelpShortcutCmdNR] = "⌘N / ⌘R",
        [StringKey.HelpShortcutCmdZ] = "⌘Z",
        [StringKey.HelpBeecellTitle] = "Freecell (Beecell)",
        [StringKey.HelpKlondikeObjective] = "Mueve las 52 cartas a las cuatro pilas de la Fundación, organizadas por palo desde el As (el más bajo) hasta el Rey (el más alto).",
        [StringKey.HelpKlondikeLayout] = "• Tablero (7 Columnas): Repartidas de izquierda a derecha con 1 a 7 cartas respectivamente. Solo la carta superior de cada columna está boca arriba.\n• Pila (Arriba a la Izquierda): Contiene las 24 cartas restantes boca abajo.\n• Descarte (Junto a la Pila): Contiene las cartas robadas de la pila.\n• Fundaciones (Arriba a la Derecha): Cuatro espacios vacíos reservados para completar cada palo.",
        [StringKey.HelpKlondikeRules] = "• Construcción del Tablero: Apila cartas en rango descendente alternando colores (ej., un 6 rojo sobre un 7 negro). Puedes mover una sola carta o una secuencia entera boca arriba a otra columna.\n• Columnas Vacías: Solo un Rey (o una secuencia que empiece con un Rey) puede colocarse en una columna vacía del tablero.\n• Pila y Descarte:\n  – Modo Robar 1: Al hacer clic en la pila se revela 1 carta al descarte.\n  – Modo Robar 3: Revela 3 cartas; solo la carta superior del descarte es jugable. Una vez jugada, la siguiente carta del grupo de 3 estará disponible.\n• Modos de Puntuación:\n  – Estándar: Voltear carta boca abajo (+5 pts) · Descarte al Tablero (+5 pts) · Descarte/Tablero a la Fundación (+10 pts) · Fundación de vuelta al Tablero (−15 pts). Deshacer retira los puntos de ese movimiento y los descuenta otra vez como penalización. Al ganar una partida con tiempo: −2 pts por cada 10 segundos jugados, y luego una bonificación de velocidad de 700.000 ÷ segundos.\n  – Vegas: Empiezas con una deuda de −$52. Gana +$5 por cada carta movida a la fundación (−$5 si una vuelve a salir de ella). Tu saldo empieza en $0 cada vez que abres el juego. Robar 1 permite solo 1 pasada por la pila; Robar 3 permite 3 pasadas (2 repartos extra).",
        [StringKey.HelpKlondikeStrategy] = "1. Prioriza Cartas Boca Abajo: Siempre prioriza movimientos que revelen cartas ocultas en las columnas más largas del tablero.\n2. Mantén Columnas Abiertas: No vacíes una columna del tablero a menos que ya tengas un Rey listo para ocuparla.\n3. Retrasa Movimientos a la Fundación: Evita apresurar cartas a la fundación temprano si podrían necesitarse para construir secuencias más bajas en el tablero.",
        [StringKey.HelpKlondikeNoStress] = "Activar el Modo Sin Estrés en Opciones desactiva el temporizador de la partida por completo.",
        [StringKey.HelpBeecellObjective] = "Mueve las 52 cartas a las cuatro pilas de la Fundación, construyéndolas por palo desde el As hasta el Rey.",
        [StringKey.HelpBeecellLayout] = "• Tablero (8 Columnas): Las 52 cartas se reparten boca arriba al inicio (4 columnas de 7 cartas, 4 columnas de 6 cartas).\n• Celdas Libres (Arriba a la Izquierda): Cuatro espacios de almacenamiento temporal.\n• Fundaciones (Arriba a la Derecha): Cuatro pilas de construcción por palo.",
        [StringKey.HelpBeecellRules] = "• Construcción del Tablero: Apila cartas en rango descendente y colores alternos.\n• Almacenamiento en Celdas Libres: Cada celda libre puede contener exactamente 1 carta a la vez.\n• Capacidad de Movimiento Múltiple: Puedes mover una secuencia de cartas boca arriba en una sola acción. El número máximo de cartas que puedes mover a la vez se calcula como: (Celdas Libres Disponibles + 1) × 2^(Columnas Vacías en el Tablero).\n• Columnas Vacías: Cualquier carta individual o secuencia válida se puede mover a una columna vacía en el tablero, pero la columna a la que mueves no cuenta para la capacidad de arriba.\n• Puntuación: +10 por cada carta movida a una fundación, −15 por retirar una de ella.",
        [StringKey.HelpBeecellStrategy] = "1. Protege Tus Celdas Libres: Trata las celdas libres como espacio de maniobra temporal. Evita llenar las cuatro celdas libres simultáneamente, ya que reduce drásticamente tu capacidad de mover secuencias.\n2. Descubre Cartas Bajas Temprano: Concéntrate en liberar Ases y Doses enterrados al fondo de las columnas.\n3. Las Columnas Vacías son Oro: Una columna vacía duplica tu capacidad de movimiento y actúa como una celda libre sin restricciones.",
        [StringKey.HelpSpiderObjective] = "Arma ocho secuencias completas del mismo palo desde el Rey hasta el As dentro del tablero. Cada secuencia completa de 13 cartas se elimina automáticamente a la fundación.",
        [StringKey.HelpSpiderLayout] = "• Tablero (10 Columnas): 54 cartas repartidas en 10 columnas (las primeras 4 tienen 6 cartas; las últimas 6 tienen 5 cartas). Solo la carta superior de cada columna está boca arriba.\n• Pila (Abajo/Arriba): Las 50 cartas restantes organizadas en 5 repartos extra de 10 cartas cada uno.",
        [StringKey.HelpSpiderRules] = "• Modos de Dificultad:\n  – 1 Palo (Fácil): Las 104 cartas son Picas.\n  – 2 Palos (Medio): 52 Picas y 52 Corazones.\n  – 4 Palos (Difícil): Se usan los cuatro palos estándar.\n• Construcción del Tablero: Apila cartas en rango descendente sin importar el palo (ej., un 7 de Corazones puede colocarse sobre un 8 de Picas). Excepción Crucial: Solo puedes mover una secuencia de múltiples cartas si todas las cartas de esa secuencia comparten el mismo palo.\n• Repartos desde la Pila: Haz clic en la pila para repartir 1 carta en cada columna del tablero. Requisito: Cada columna debe contener al menos 1 carta antes de que puedas repartir desde la pila.\n• Puntuación: Empiezas con 500 puntos; cada movimiento o reparto cuesta 1 punto, y cada secuencia completa de Rey a As suma 100.",
        [StringKey.HelpSpiderStrategy] = "1. Mismo Palo Antes que Palos Mixtos: Siempre prioriza construir rachas del mismo palo. Las pilas de palos mixtos bloquean tus cartas y no pueden moverse juntas.\n2. Columnas Vacías Primero: Las columnas vacías te permiten aislar pilas de palos mixtos y reorganizarlas en limpias rachas del mismo palo.\n3. Retrasa el Reparto: Agota cada movimiento posible en el tablero antes de hacer clic en la pila.",
        [StringKey.HelpVideopokerObjective] = "Roba una mano de 5 cartas que coincida con una entrada válida en la tabla de pagos para ganar multiplicadores de créditos.",
        [StringKey.HelpVideopokerHowToPlay] = "1. Apuestas: Selecciona 1 a 5 monedas. Presiona Apuesta Máxima (M) para apostar 5 monedas y repartir de inmediato. (Nota: El premio de 800× por la Escalera Real solo se otorga con una apuesta de 5 monedas).\n2. Repartir y Retener: Presiona Repartir (Espacio). Haz clic en las cartas o presiona 1–5 para alternar RETENER (HOLD) en las cartas que desees guardar.\n3. Robar: Presiona Robar (Espacio). Las cartas no retenidas son reemplazadas. Las ganancias se pagan según la tabla de pagos.\n\nVariantes de Juego:\n• Jacks or Better: Tabla de pagos estándar. La mano mínima para calificar es un par de Jotas, Reinas, Reyes o Ases (1×).\n• Deuces Wild: Los cuatro 2s son comodines. La mano ganadora mínima es Tercia. Pagos especiales por Cuatro Doses (200×) y Escalera Real Comodín (25×).\n• Bonus Poker: Pagos mejorados por Póker (Cuatro Ases paga 80×; Cuatro 2s/3s/4s paga 40×).",
        [StringKey.HelpVideopokerStrategy] = "1. Siempre Haz Apuesta Máxima (5 Monedas): El pago por la Escalera Real salta de 250× a 800× solo con 5 monedas.\n2. Nunca Rompas una Mano Armada (Excepto por 4-para-Escalera Real): Solo rompe una Escalera o Color si estás a 1 carta de una Escalera Real.\n3. En Deuces Wild, Nunca Descartes un 2: Los dos son comodines—¡siempre retén cada 2 que te repartan!",
        [StringKey.HelpVideopokerNoStress] = "Activar el Modo Sin Estrés en Opciones cambia el juego a Juego Libre—ocultando apuestas, créditos y tablas de pagos para que puedas jugar sin riesgos ni apuestas.",
        [StringKey.HelpBlackjackObjective] = "Supera el total de la mano del repartidor sin pasarte de 21. Cartas de Figura = 10, Ases = 1 u 11, Cartas Numéricas = valor nominal.",
        [StringKey.HelpBlackjackRules] = "1. Haz Apuesta y Reparte: Arma tu apuesta con las fichas (1, 5, 10, 25, o 2X para duplicarla), luego presiona Repartir (Espacio).\n2. Tu Turno:\n  – Pedir (H): Toma otra carta.\n  – Plantarse (S): Mantén tu mano actual.\n  – Doblar (D): Dobla tu apuesta, recibe exactamente 1 carta, y te plantas automáticamente. (Disponible en las 2 cartas iniciales con un total de 9, 10, u 11).\n  – Dividir (P): Si se te reparten dos rangos iguales, divídelos en dos manos separadas (requiere una segunda apuesta igual). Una división por ronda; los Ases divididos reciben exactamente una carta más cada uno.\n3. Turno del Repartidor: El repartidor revela su carta oculta y debe pedir hasta alcanzar 17 o más (se planta en todos los 17s). Si todas tus manos se pasaron, o tienes un natural, el repartidor solo revela su carta y no pide. El natural del repartidor se revisa en cuanto se reparten las cartas: gana a todo excepto a tu propio natural (empate).\n\nEsquema de Pagos:\n• Ganancia Estándar: pago 1:1.\n• Blackjack Natural (As + carta de valor 10, en una mano sin dividir): pago 3:1.\n• Empate (Push): Se devuelve la apuesta.",
        [StringKey.HelpBlackjackStrategy] = "1. Siempre Divide Ases y 8s: Nunca dividas 10s o 5s.\n2. Dobla con 11: Siempre Dobla cuando tu mano inicial sume 11 contra un repartidor del 2 al 10.\n3. Observa la Carta Abierta del Repartidor: Si el repartidor muestra del 2 al 6, tiene una alta probabilidad de pasarse—plántate con 12 duro o más y deja que el repartidor robe.",
        [StringKey.HelpBlackjackNoStress] = "Activar el Modo Sin Estrés en Opciones cambia el juego a Juego Libre—ocultando apuestas y créditos para que puedas jugar sin riesgos ni apuestas.",
        [StringKey.HelpHoneycombObjective] = "Lucha contra un oponente de la IA en una cuadrícula de 3×3 usando un mazo de 5 cartas. Cada carta cuenta con 4 estadísticas direccionales (Arriba, Derecha, Abajo, Izquierda). Coloca las cartas estratégicamente para voltear las cartas enemigas a tu color. Cuando la cuadrícula se llena, cada lado suma las cartas que controla en el tablero más las que aún tiene en la mano: ¡gana la puntuación más alta!",
        [StringKey.HelpHoneycombMechanics] = "• Capturas: Cuando colocas una carta adyacente a la de un oponente, tu estadística de cara se compara con su estadística de cara opuesta. Si tu estadística es mayor, la carta enemiga es capturada (volteada a tu color). La estadística 10 se representa como \"A\".\n• Mentes Colmena: Cuando Simetría o Abeja Matemática capturan cartas, cada carta capturada ataca a sus propios vecinos como si acabara de colocarse, ¡lo que puede desatar una reacción en cadena de capturas! (Una captura normal por estadística mayor no inicia una cadena.)",
        [StringKey.HelpHoneycombCardBank] = "• Mecánica de Robo: Después de ganar una partida, elige Roba una Carta y haz doble clic (doble toque en el teléfono) en una de las cartas del oponente que capturaste, ¡para añadirla a tu Banco de Cartas para siempre! Solo se permite un robo por partida.\n• Límites de Rareza de Mazo: Los mazos personalizados están limitados a: como máximo una carta de 5★, y como máximo una carta de 4★ si hay una de 5★ presente (o hasta dos cartas de 4★ sin una de 5★).\n• Mazos de Oponente Inteligentes: La IA selecciona automáticamente mazos que contienen cartas que aún no tienes para maximizar las recompensas de robo.\n• Protección Anti-Robo: ¿Atrapado en una cadena de Revanchas contra un oponente cuyas cartas parece que no puedes capturar? Gana dos Revanchas seguidas contra el mismo oponente sin que haya nada elegible para robar, y cualquier carta aún no desbloqueada que quede en el tablero se vuelve robable en esa segunda victoria — capturada o no. Una vez activada, se mantiene activa para el resto de esa cadena de Revanchas, para que cada victoria futura siga ofreciendo un robo — no tendrás que volver a ganarlo. Esto se desactiva al comenzar una Nueva Partida (contra un nuevo oponente).",
        [StringKey.HelpHoneycombNoStress] = "Activar el Modo Sin Estrés en Opciones te reparte un mazo fuerte al azar en cada partida y oculta las mecánicas de Robo de Cartas.",
        [StringKey.HelpCustomizationThemes] = "• Mesa de Fieltro: Elige entre 5 colores de fieltro preestablecidos (Verde, Carmesí, Azul Real, Carbón, Desierto) o establece un Color Personalizado. Activa/desactiva la viñeta de los bordes.\n• Reversos de Cartas: Selecciona diseños incorporados o sube archivos .jpg/.png/.gif personalizados.\n• Arte de Cartas de Figura: Sube arte de imagen/GIF personalizado individualmente para Ases, Jotas, Reinas y Reyes.\n• Temas Guardados: ¡Guarda un instante de tu fieltro, reversos de cartas y arte de figuras en temas personalizados con nombre para aplicarlos en cualquier momento con un solo clic!",
        [StringKey.HelpCustomizationOptions] = "• Modo Miel: Interruptor global en los 6 juegos — controla las ventanas emergentes de puntuación \"+N\"/\"-N\" y si aparecen los carteles de sabor/ambiente. Desactívalo para una experiencia de juego más silenciosa y minimalista.\n• Siempre Encima: Mantiene la ventana del juego anclada sobre tus otras ventanas (Menú Vista).\n• Efectos de Sonido, Puntuación Vegas, y Ocultar Botón de Pistas también están disponibles aquí por juego.",
        [StringKey.HelpKlondikeTitle] = "Solitario Klondike",
        [StringKey.HelpKlondikeSubtitle] = "Clásico solitario de un mazo con opciones de Robar 1, Robar 3 y puntuación Vegas.",
