        [StringKey.BeekeeperGardenPlant] = "Plantar",
        [StringKey.BeekeeperGardenGrowing] = "¡Algo está creciendo!",
        [StringKey.BeekeeperGardenEmpty] = "Todavía no hay nada plantado.",
        [StringKey.BeekeeperPlantWildflowers] = "Flores silvestres",
        [StringKey.BeekeeperPlantWildflowersBlurb] = "Un goteo constante de polen.",
