        [StringKey.BeekeeperLogPlantBramble] = "¡Una zarzamora! Las abejas guardianas se instalan entre sus espinas.",
        [StringKey.BeekeeperLogFirstPollen] = "Una recolectora vuelve a casa cubierta de polen.",
        [StringKey.BeekeeperLogBeeBread] = "Empaquetas polen y miel en pan de abejas.",
        [StringKey.BeekeeperLogWoodenHive] = "Mudas a las abejas a una colmena de madera. Parecen contentas.",
        [StringKey.BeekeeperLogWaspRaidGuardsFmt] = "La avispa se sirve %@ de miel. Las guardianas protegen a todas las abejas.",
        [StringKey.BeekeeperLogShoeMissGuardsFmt] = "Fallaste. La avispa se sirve %@ de miel. Las guardianas protegen a todas las abejas.",
        [StringKey.HelpBeekeeperGardenTitle] = "🌱 El jardín",
        [StringKey.HelpBeekeeperGarden] = "Los hippies y las avispas a veces te dan una semilla, y puedes ver de qué es. Plántala en tu bancal (crece una semilla a la vez) y espera: cada planta tarda su tiempo en brotar, incluso con la aplicación cerrada, y le da a tu colmena una especialidad.\n\nLas flores silvestres y el trébol dan recolección: 3 de polen por minuto cada una. El polen y la miel hacen pan de abejas en el banco de trabajo, y el pan de abejas junto con cera sirve para mudar a tus abejas a una colmena de madera, donde los panales hacen más miel. Una zarzamora da guardia: los panales hacen un 25% más de miel. El sauce (cerca de una hora) da crianza: la reina pone un 50% más rápido y también come más pan de abejas. El álamo (unas 6 horas, una semilla de las avispas cuando comercias con ellas) da resina: las abejas recogen propóleo, que se usa en velas y en el sello de propóleo. El trébol tarda unas 12 horas.\n\nEl papel de las avispas compra el cuaderno del apicultor, con una nota sobre cada cosa que sabe hacer tu colmena.",
        [StringKey.BeekeeperLogTradeBearFmt] = "Le cambias a %@ %@ de miel por %@ Beebits.",
        [StringKey.BeekeeperLogTradeBearOneFmt] = "Le cambias a %@ %@ de miel por 1 Beebit.",
